/**
 * Barrel and generated-file detection (EXP368, Fix 4).
 *
 * A barrel file re-exports symbols from other modules without adding logic;
 * its exports are "used" by virtue of being re-exports, NOT dead. EXP357
 * mis-flagged barrel exports as dead (40-80% FP rate).
 *
 * A generated file is one with a banner comment indicating it was produced
 * by codegen (`auto-generated`, `do not edit`, `@generated`, etc.). Generated
 * files are public API surface; their exports are not dead within the repo.
 *
 * This module exposes pure predicates used by `dead-exports.ts`. One owner
 * for both detection rules — checks consume this, they don't reimplement it.
 */

import type { ParsedFile } from "../base.ts";

const GENERATED_BANNERS: readonly RegExp[] = [
  /@generated/i,
  /auto[- ]generated/i,
  /do not edit/i,
  /do not modify/i,
  /generated by/i,
  /code-?generated/i,
  /eslint-disable.*generated/i,
];

/** Heuristic: a barrel file has >0 exports and few/no function/class symbols.
 * Thresholds (max non-exported symbols, min exports) come from config — but
 * the defaults here are conservative. */
export interface BarrelDetectionConfig {
  /** A file with at most this many non-exported symbols AND at least this
   * many exports is considered a barrel. */
  readonly maxNonExportedSymbols: number;
  readonly minExports: number;
}

const DEFAULT_BARREL_CONFIG: BarrelDetectionConfig = {
  maxNonExportedSymbols: 2,
  minExports: 3,
};

export function isGeneratedFile(file: ParsedFile): boolean {
  // Check the first 600 chars of the file (generated banners are at the top).
  const head = file.content.slice(0, 600);
  for (const re of GENERATED_BANNERS) {
    if (re.test(head)) return true;
  }
  // Also check comments at the top of the file.
  for (const c of file.comments) {
    if (c.line > 20) break;
    for (const re of GENERATED_BANNERS) {
      if (re.test(c.text)) return true;
    }
  }
  return false;
}

export function isBarrelFile(file: ParsedFile, cfg: BarrelDetectionConfig = DEFAULT_BARREL_CONFIG): boolean {
  // Generated files are not barrels per se, but they share the same
  // exclusion (exports are not dead). The caller checks generated first.
  const exports = file.exports;
  if (exports.length < cfg.minExports) return false;
  const nonExportedSymbols = file.symbols.filter((s) => !s.exported).length;
  if (nonExportedSymbols > cfg.maxNonExportedSymbols) return false;
  // Re-export shape: most of the file's content should be `export... from`
  // or `export { x }` statements (JS/TS), `pub use` (Rust), `from X import Y`
  // (Python `__init__.py`). Approximate by counting export lines vs total lines.
  if (file.loc > 0 && exports.length / file.loc > 0.05) return true;
  // Python __init__.py files are conventionally barrels.
  if (file.path.endsWith("/__init__.py") || file.path === "__init__.py") return true;
  // JS/TS index.{ts,js} files at package roots are conventionally barrels.
  if (/(^|\/)index\.(ts|tsx|js|jsx|mjs|cts|mts)$/.test(file.path)) {
    // Refine: only if it has re-exports (`export... from`) and few functions.
    const hasReExport = /export\s+\*\s+from|export\s+\{[^}]+\}\s+from/.test(file.content);
    if (hasReExport && nonExportedSymbols <= cfg.maxNonExportedSymbols) return true;
  }
  return false;
}

/** Convenience: should the dead-export check skip this file's exports? */
export function shouldExcludeFromDeadExport(file: ParsedFile, cfg: BarrelDetectionConfig = DEFAULT_BARREL_CONFIG): boolean {
  return isGeneratedFile(file) || isBarrelFile(file, cfg);
}
